import {rankFor,rankLabel,rankNames,rankMilestones,legacyRankFor} from './engine.js';
// Original 96×160 raster sprite, 16 authored frames per rank. No runtime canvas.
export function judah(completed=0,pose='idle',caption=true,equipment=[],wardrobe){
 const rank=rankFor(completed),visual=rankNames.includes(wardrobe)?wardrobe:rank.name,stage=rankNames.indexOf(visual),legacy=stage>rankNames.indexOf(rank.name);
 const action=['stance','ready','slash','celebrate','recoil','walk','run','victory','transform'].includes(pose);
 const safePose=action||['idle','success','reflection','advance'].includes(pose)?pose:'idle';
 const sheet=`assets/console/judah-${visual.toLowerCase()}${action?'-adventure':''}.png`;
 const belt=equipment.includes('belt')?` data-armor="belt"`:'';
 const armorSheet=equipment.includes('belt')?`;--armor-sheet:url('assets/armor/belt-${visual.toLowerCase()}${action?'-adventure':''}.png')`:'';
 const before=legacy?visual.toLowerCase():rank.degree>1?'master':rankNames[Math.max(0,stage-1)].toLowerCase();
 return `<figure class="judah judah-${safePose} judah-stage-${stage} ${action?'judah-adventure':''}" data-pose="${safePose}" data-rank="${rank.name}" data-degree="${rank.degree}" style="--master-glow:${Math.min(10,rank.degree)+3}px">${action?'<span class="judah-art-frame">':''}<span class="judah-sprite"${belt} role="img" aria-label="Judah · ${rankLabel(rank)}${legacy?` · Legacy ${visual} wardrobe`:""}${equipment.includes('belt')?' · Belt of Truth':''}" style="--sheet:url('${sheet}')${armorSheet}"></span>${safePose==='transform'?`<span class="rank-before"${belt} style="--sheet:url('assets/console/judah-${before}-adventure.png')${equipment.includes('belt')?`;--armor-sheet:url('assets/armor/belt-${before}-adventure.png')`:''}" aria-hidden="true"></span>`:''}${action?'</span>':''}${safePose==='slash'?'<span class="hero-slash" aria-hidden="true"></span>':''}${rank.degree?`<span class="judah-degree" aria-hidden="true">${'◆'.repeat(Math.min(8,rank.degree))}</span>`:''}${caption?`<figcaption><b>JUDAH</b><span>${rankLabel(rank)}</span></figcaption>`:''}</figure>`;
}
export function judahJourney(completed,equipment=[],legacyCompleted=0){const legacyStage=rankNames.indexOf(legacyRankFor(legacyCompleted).name);return `<section class="judah-journey"><h2>Judah’s journey</h2><p>Wardrobes unlock permanently after completed levels. Earlier wardrobe unlocks remain available as legacy honors.</p><div class="judah-ranks">${rankMilestones.map((n,i)=>{const earned=completed>=n,legacy=!earned&&i<=legacyStage;return `<article class="${earned||legacy?'earned':'unearned'}">${judah(n,'idle',true,equipment)}<small>${earned?'EARNED':legacy?'LEGACY UNLOCK':`PREVIEW · CLEAR ${n} LEVELS`}</small></article>`}).join('')}</div><p>Master begins after Level 260. Each additional 75 completed levels adds a degree without a wardrobe replacement. The decorative insignia shows up to eight diamonds; the title continues beyond eight degrees.</p></section>`}
